#include "../src/hsd_scene.h"
#include <stdio.h>
#include <math.h>
static bool load(std::vector<unsigned char>& raw){FILE* f=fopen("C:\\Users\\luizf\\Documents\\melee_extraido\\MnSlChr.usd","rb");if(!f)return false;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);raw.resize(n);bool ok=fread(&raw[0],1,n,f)==(size_t)n;fclose(f);return ok;}
static void dump(Melee360Scene& scene,const char* path){FILE* fp=fopen(path,"wb");if(!fp)return;unsigned int n=(unsigned int)scene.textures.size();fwrite(&n,4,1,fp);for(unsigned int i=0;i<n;++i){Melee360SceneTexture& t=scene.textures[i];fwrite(&t.width,4,1,fp);fwrite(&t.height,4,1,fp);fwrite(&t.pixels[0],4,t.width*t.height,fp);}n=(unsigned int)scene.batches.size();fwrite(&n,4,1,fp);for(unsigned int i=0;i<n;++i){Melee360SceneBatch& b=scene.batches[i];unsigned int count=(unsigned int)b.vertices.size();fwrite(&b.texture,4,1,fp);fwrite(&b.mode,4,1,fp);fwrite(&b.wrapS,4,1,fp);fwrite(&b.wrapT,4,1,fp);fwrite(&count,4,1,fp);fwrite(&b.vertices[0],sizeof(Melee360SceneVertex),count,fp);}fclose(fp);}
int main(){std::vector<unsigned char> raw;if(!load(raw))return 1;for(int icon=0;icon<25;++icon){Melee360CSSInit();if(!Melee360CSSPlaceAtIcon(icon))return 2;for(int phase=0;phase<2;++phase){if(phase&&!Melee360CSSConfirm())return 3;Melee360CSSState state;Melee360CSSGetState(&state);Melee360Scene scene;if(!Melee360LoadCharacterSelect(&raw[0],(unsigned int)raw.size(),icon,scene,120,true,&state)||scene.skipped)return 4;if(icon==0)dump(scene,phase?"css-dropped.bin":"css-held.bin");for(unsigned int i=0;i<scene.batches.size();++i)for(unsigned int v=0;v<scene.batches[i].vertices.size();++v)for(int k=0;k<4;++k)if(!_finite(scene.batches[i].vertices[v].clip[k]))return 5;}}
 puts("Original CSS visual boundary: 50 held/dropped poses, all 25 icons, original hand/token geometry, no skipped meshes passed");return 0;}
